properties.query:
// This rule detects enumeration activity
// The commands will list user's that are hidden on the login screen, such as admin
let Parent_Process = dynamic(["cmd.exe","powershell.exe"]);
let cmd_all = dynamic(["add","/t REG_DWORD","/v","/d 0","SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon\\SpecialAccounts\\UserList"]);
_Im_ProcessCreate(commandline_has_all=cmd_all,parentprocess_has_any=Parent_Process,target_process_has_any="reg.exe")
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
